/// Verifies that a buffer of bytes contains a `AIS`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_ais_unchecked`.
#[inline]
pub fn root_as_ais(buf: &[u8]) -> Result<AIS<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<AIS>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `AIS` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_ais_unchecked`.
#[inline]
pub fn size_prefixed_root_as_ais(buf: &[u8]) -> Result<AIS<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<AIS>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `AIS` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_ais_unchecked`.
#[inline]
pub fn root_as_ais_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<AIS<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<AIS<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `AIS` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_ais_unchecked`.
#[inline]
pub fn size_prefixed_root_as_ais_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<AIS<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<AIS<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a AIS and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `AIS`.
#[inline]
pub unsafe fn root_as_ais_unchecked(buf: &[u8]) -> AIS<'_> {
    unsafe { ::flatbuffers::root_unchecked::<AIS>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed AIS and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `AIS`.
#[inline]
pub unsafe fn size_prefixed_root_as_ais_unchecked(buf: &[u8]) -> AIS<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<AIS>(buf) }
}

pub const AIS_IDENTIFIER: &str = "$AIS";

#[inline]
pub fn ais_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, AIS_IDENTIFIER, false)
}

#[inline]
pub fn ais_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, AIS_IDENTIFIER, true)
}

#[inline]
pub fn finish_ais_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<AIS<'a>>
) {
    fbb.finish(root, Some(AIS_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_ais_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<AIS<'a>>
) {
    fbb.finish_size_prefixed(root, Some(AIS_IDENTIFIER));
}
